#!/usr/bin/env python3
"""Offline Windows photo sender. Copy only transfer_photos.py to the internal PC.

Requires standard Python 3.8+, FFmpeg and a modern Chrome/Edge browser.
Embeds the unmodified Decimen v0.5.3 sender (AGPL-3.0-or-later).
Source: https://github.com/bashalarmistalt/decimen-optical-transfer/tree/v0.5.3
"""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import webbrowser
import zipfile
import zlib

# Generated from compress.py by tools/build_portable.py.
EXTENSIONS = {".jpg", ".jpeg", ".png", ".webp", ".tif", ".tiff", ".bmp", ".heic", ".heif", ".avif"}

MAX_BYTES = 10_000_000

def compress(source, destination, edge=2048, quality=3, max_bytes=MAX_BYTES, ffmpeg="ffmpeg"):
    destination.parent.mkdir(parents=True, exist_ok=True)
    if destination.exists():
        raise FileExistsError(f"Output already exists: {destination}")
    with tempfile.TemporaryDirectory(dir=destination.parent) as temporary:
        candidate = Path(temporary) / "photo.jpg"
        for _ in range(20):
            scale = f"scale=w='min({edge},iw)':h='min({edge},ih)':force_original_aspect_ratio=decrease"
            subprocess.run([
                ffmpeg, "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
                "-i", str(source), "-frames:v", "1", "-vf", scale,
                "-map_metadata", "-1", "-c:v", "mjpeg", "-q:v", str(quality),
                "-pix_fmt", "yuvj420p", "-update", "1", str(candidate),
            ], check=True, capture_output=True)
            if candidate.stat().st_size < max_bytes:
                # A hard link publishes atomically and refuses to replace an existing file.
                os.link(candidate, destination)
                return destination.stat().st_size
            edge = max(16, int(edge * 0.8))
        raise ValueError(f"Cannot compress below {max_bytes} bytes: {source}")

